target.css:
:root {
  --ink: #26342e;
  --muted: #69766f;
  --card: #fffdf7;
  --line: #dbe3d8;
  --moss: #315f4c;
  --mint: #dcefe4;
  --sun: #f4c95d;
  --sun-soft: #fff2c9;
  --white: #ffffff;
}

.count-card {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background-color: var(--card);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.marker {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 12px;
  background-color: var(--sun-soft);
  font-size: 21px;
}

.title-block {
  min-width: 0;
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.05em;
  line-height: 1.2;
  text-transform: uppercase;
}

.title-block h1 {
  margin: 0;
  font-size: 19px;
  font-weight: 750;
  line-height: 1.15;
}

.status {
  padding: 5px 9px;
  border-radius: 999px;
  background-color: var(--mint);
  color: var(--moss);
  font-size: 12px;
  font-weight: 750;
}

.count-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background-color: var(--moss);
  color: var(--white);
}

.count-number {
  margin: 0;
  font-size: 35px;
  font-weight: 800;
  line-height: 0.95;
}

.count-copy {
  margin: 0;
  font-size: 13px;
  line-height: 1.3;
}

.count-copy strong {
  color: var(--sun);
  font-weight: 750;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0;
  padding: 0;
  list-style: none;
}

.metrics li {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-height: 62px;
  padding: 11px 16px;
  border-right: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  line-height: 1.2;
}

.metrics li:last-child {
  border-right: 0;
}

.metric-icon {
  font-size: 16px;
}

.metrics strong {
  display: block;
  color: var(--ink);
  font-size: 14px;
  font-weight: 800;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
}

.route {
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
}

.card-footer button {
  border: 0;
  border-radius: 9px;
  padding: 8px 12px;
  background-color: var(--sun);
  color: var(--ink);
  font-size: 12px;
  font-weight: 800;
  line-height: 1;
}

